glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
in vec4 v_color;
in vec2 v_uv0;
uniform sampler2D texture;
float startX = 0.0;
float thresholdX = 0.08;
float blur = 0.01;
float posInterval = 0.02;
uniform ARGS {
  vec2 iResolution;
  float time;
};
float colFactor(vec2 uv, float thresholdX, float blur){
    float intervalY = uv.y;
    float tempX = intervalY * cos(radians(60.0)) + startX;
    float intervalX = uv.x - tempX;
    return smoothstep(thresholdX, thresholdX - blur, abs(intervalX));
}
void mainImage( out vec4 fragColor, in vec2 fragCoord ,vec2 res)
{
    vec2 uv = fragCoord/res.xy;
    startX = tan(time * 3.);
    float factor = colFactor(uv, thresholdX, blur);
    vec4 texColor = texture2D(texture,v_uv0);
    vec4 factorColor = factor * vec4(1.0, 1., 1., 1.0) + texColor * (1.0 - factor);
    fragColor = factorColor;
}
void main () {
  vec2 res = vec2(300.,300.);
  mainImage(gl_FragColor,v_uv0.xy * res.xy,res);
}

